db_calls = 0
cache = {}
def get_story(sid):
    global db_calls
    if sid in cache:
        return cache[sid]
    db_calls += 1          # 캐시에 없을 때만 DB
    cache[sid] = {"id": sid}
    return cache[sid]
for sid in [1, 2, 1, 1, 3, 2, 1, 1, 1, 2]:
    get_story(sid)
print(f"요청 10번 중 DB {db_calls}번 → 캐시 적중률 {(10 - db_calls) / 10:.0%}")
# 요청 10번 중 DB 3번 → 캐시 적중률 70%
